import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().go();
    }

    void go() {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        Task solver = new Task();
        solver.run(1, in, out);
        out.close();
    }

    static class Task {
        private static final long MOD = 1000000007L;
        private static final long INF = (long)1e18 + 1;
        private long[][] comb = new long[100][100];

        private long combine(long base, int n1, int k1, int n2, int k2) {
            base = (base * comb[n1][k1]) % MOD;
            base = (base * comb[n2][k2]) % MOD;
            return base;
        }

        void run(int testId, InputReader in, OutputWriter out) {
            int N = in.nextInt();
            int K = in.nextInt();
            int cnt50 = 0, cnt100 = 0;
            for (int i = 0; i < N; i++) {
                int val = in.nextInt();
                if (val == 50) cnt50++;
                else cnt100++;
            }

            // Precompute combinations
            for (int i = 0; i < 100; i++) {
                comb[i][0] = comb[i][i] = 1;
                for (int j = 1; j < i; j++) {
                    comb[i][j] = (comb[i-1][j] + comb[i-1][j-1]) % MOD;
                }
            }

            long[][][] dist = new long[200][200][2];
            long[][][] count = new long[200][200][2];
            for (int i = 0; i < 200; i++) {
                for (int j = 0; j < 200; j++) {
                    Arrays.fill(dist[i][j], INF);
                    Arrays.fill(count[i][j], 0);
                }
            }

            dist[0][0][0] = 0;
            count[0][0][0] = 1;

            Queue<Node> q = new LinkedList<>();
            q.add(new Node(0, 0, 0, 0));

            while (!q.isEmpty()) {
                Node node = q.poll();
                int x = node.x;
                int y = node.y;
                int side = node.side;
                long d = dist[x][y][side];

                if (side == 0) {
                    int rem50 = cnt50 - x;
                    int rem100 = cnt100 - y;
                    for (int take50 = 0; take50 <= rem50; take50++) {
                        for (int take100 = 0; take100 <= rem100; take100++) {
                            if (take50 == 0 && take100 == 0) continue;
                            int w = take50 * 50 + take100 * 100;
                            if (w > K) break;
                            int nx = x + take50;
                            int ny = y + take100;
                            int nextSide = side ^ 1;
                            if (dist[nx][ny][nextSide] >= d + 1) {
                                if (dist[nx][ny][nextSide] > d + 1) {
                                    dist[nx][ny][nextSide] = d + 1;
                                    q.add(new Node(nx, ny, nextSide, d + 1));
                                    count[nx][ny][nextSide] = (count[nx][ny][nextSide] + combine(count[x][y][side], rem50, take50, rem100, take100)) % MOD;
                                } else {
                                    count[nx][ny][nextSide] = (count[nx][ny][nextSide] + combine(count[x][y][side], rem50, take50, rem100, take100)) % MOD;
                                }
                            }
                        }
                    }
                } else {
                    int rem50 = x;
                    int rem100 = y;
                    for (int take50 = 0; take50 <= rem50; take50++) {
                        for (int take100 = 0; take100 <= rem100; take100++) {
                            if (take50 == 0 && take100 == 0) continue;
                            int w = take50 * 50 + take100 * 100;
                            if (w > K) break;
                            int nx = x - take50;
                            int ny = y - take100;
                            int nextSide = side ^ 1;
                            if (dist[nx][ny][nextSide] >= d + 1) {
                                if (dist[nx][ny][nextSide] > d + 1) {
                                    dist[nx][ny][nextSide] = d + 1;
                                    q.add(new Node(nx, ny, nextSide, d + 1));
                                    count[nx][ny][nextSide] = (count[nx][ny][nextSide] + combine(count[x][y][side], rem50, take50, rem100, take100)) % MOD;
                                } else {
                                    count[nx][ny][nextSide] = (count[nx][ny][nextSide] + combine(count[x][y][side], rem50, take50, rem100, take100)) % MOD;
                                }
                            }
                        }
                    }
                }
            }

            if (dist[cnt50][cnt100][1] == INF) {
                out.println(-1);
            } else {
                out.println(dist[cnt50][cnt100][1]);
            }
            out.println(count[cnt50][cnt100][1]);
        }

        static class Node {
            int x, y, side;
            long dist;
            Node(int x, int y, int side, long dist) {
                this.x = x;
                this.y = y;
                this.side = side;
                this.dist = dist;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int ptr = 0, len = 0;

        public InputReader(InputStream stream) {
            in = stream;
        }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        public int nextInt() {
            int c;
            while ((c = read()) <= ' ') {}
            int val = 0;
            do {
                val = val * 10 + (c - '0');
            } while ((c = read()) > ' ');
            return val;
        }
    }

    static class OutputWriter {
        private final PrintWriter out;

        public OutputWriter(OutputStream stream) {
            out = new PrintWriter(stream);
        }

        public void println(long x) {
            out.println(x);
        }

        public void close() {
            out.close();
        }
    }
}
